CREATE OR REPLACE FUNCTION public.create_marketplace_checkout(_items jsonb,_shipping_address jsonb,_shipping_quote_ids jsonb,_coupon_id uuid DEFAULT NULL,_warranty_id text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE order_id uuid; warranty_price numeric; warranty_title text; tx_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta.'; END IF; IF _warranty_id IS NOT NULL THEN CASE _warranty_id WHEN '1_year' THEN warranty_price:=5;warranty_title:='1 ano'; WHEN '1_5_years' THEN warranty_price:=6;warranty_title:='1 ano e meio'; WHEN '2_years' THEN warranty_price:=7;warranty_title:='2 anos'; ELSE RAISE EXCEPTION 'Garantia inválida.'; END CASE; END IF; order_id:=public.create_marketplace_order_v3(_items,_shipping_address,_shipping_quote_ids,_coupon_id); IF warranty_price IS NOT NULL THEN SELECT id INTO tx_id FROM public.payment_transactions WHERE order_id=create_marketplace_checkout.order_id ORDER BY created_at,id LIMIT 1 FOR UPDATE; IF tx_id IS NULL THEN RAISE EXCEPTION 'Pedido sem transação.'; END IF; UPDATE public.orders SET total=total+warranty_price,platform_fee=platform_fee+warranty_price,shipping_address=coalesce(shipping_address,'{}'::jsonb)||jsonb_build_object('warranty',jsonb_build_object('id',_warranty_id,'title',warranty_title,'amount',warranty_price)) WHERE id=order_id; UPDATE public.payment_transactions SET gross_amount=gross_amount+warranty_price,platform_fee=platform_fee+warranty_price WHERE id=tx_id; END IF; RETURN order_id; END $$;
REVOKE ALL ON FUNCTION public.create_marketplace_checkout(jsonb,jsonb,jsonb,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_marketplace_checkout(jsonb,jsonb,jsonb,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.expire_club_pix_memberships() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles p SET is_clube_hs=false WHERE is_clube_hs AND EXISTS(SELECT 1 FROM public.clube_hs_pix_payments c WHERE c.user_id=p.id AND c.status='approved') AND NOT public.club_has_access(p.id); END $$;
REVOKE ALL ON FUNCTION public.expire_club_pix_memberships() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.expire_club_pix_memberships() TO service_role;
CREATE POLICY social_audio_upload_club_only ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'social-stories' OR name!~* '\.(webm|ogg|m4a|mp3|wav)$' OR public.club_has_access(auth.uid()));
CREATE POLICY trend_upload_active_club ON public.trend_videos AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') OR public.club_has_access(auth.uid()));
CREATE POLICY trend_storage_active_club ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'trend-videos' OR public.has_role(auth.uid(),'admin') OR public.club_has_access(auth.uid()));